     1	/**
     2	 * Label rows and the issue↔label join table.
     3	 */
     4	import { and, asc, eq, inArray } from "drizzle-orm";
     5	import { newId } from "@/lib/id";
     6	import { getDb, issueLabels, labels } from "@/server/db";
     7	import { toIsoTimestamp } from "@/types/common";
     8	import { orgPredicate } from "./base-repository";
     9	import { toLabel } from "./_mappers";
    10	import type { CreateLabelInput, UpdateLabelInput } from "@/schemas/label";
    11	import type { IssueId, LabelId, OrgId } from "@/types/common";
    12	import type { IssueLabel } from "@/types/issue";
    13	
    14	export async function listLabels(
    15	  orgId: OrgId,
    16	): Promise<readonly IssueLabel[]> {
    17	  const rows = getDb()
    18	    .select()
    19	    .from(labels)
    20	    .where(orgPredicate(labels.orgId, orgId))
    21	    .orderBy(asc(labels.name))
    22	    .all();
    23	  return rows.map(toLabel);
    24	}
    25	
    26	export async function insertLabel(
    27	  input: CreateLabelInput,
    28	): Promise<IssueLabel> {
    29	  const stamp = toIsoTimestamp(new Date());
    30	  const row = getDb()
    31	    .insert(labels)
    32	    .values({
    33	      id: newId(),
    34	      orgId: input.orgId,
    35	      name: input.name,
    36	      color: input.color,
    37	      description: input.description,
    38	      createdAt: stamp,
    39	      updatedAt: stamp,
    40	    })
    41	    .returning()
    42	    .get();
    43	
    44	  return toLabel(row);
    45	}
    46	
    47	export async function updateLabel(
    48	  input: UpdateLabelInput,
    49	): Promise<IssueLabel> {
    50	  const row = getDb()
    51	    .update(labels)
    52	    .set({
    53	      ...(input.name === undefined ? {} : { name: input.name }),
    54	      ...(input.color === undefined ? {} : { color: input.color }),
    55	      ...(input.description === undefined
    56	        ? {}
    57	        : { description: input.description }),
    58	      updatedAt: toIsoTimestamp(new Date()),
    59	    })
    60	    .where(
    61	      and(orgPredicate(labels.orgId, input.orgId), eq(labels.id, input.labelId)),
    62	    )
    63	    .returning()
    64	    .get();
    65	
    66	  if (!row) throw new Error(`Label ${input.labelId} not found`);
    67	  return toLabel(row);
    68	}
    69	
    70	/** Labels are hard deleted; the join rows go with them. */
    71	export async function deleteLabel(
    72	  orgId: OrgId,
    73	  labelId: LabelId,
    74	): Promise<void> {
    75	  const db = getDb();
    76	  db.delete(issueLabels)
    77	    .where(
    78	      and(
    79	        orgPredicate(issueLabels.orgId, orgId),
    80	        eq(issueLabels.labelId, labelId),
    81	      ),
    82	    )
    83	    .run();
    84	  db.delete(labels)
    85	    .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, labelId)))
    86	    .run();
    87	}
    88	
    89	/** Replaces the whole label set of one issue in a single round trip. */
    90	export async function setIssueLabels(
    91	  orgId: OrgId,
    92	  issueId: IssueId,
    93	  labelIds: readonly LabelId[],
    94	): Promise<void> {
    95	  const db = getDb();
    96	  db.delete(issueLabels)
    97	    .where(
    98	      and(
    99	        orgPredicate(issueLabels.orgId, orgId),
   100	        eq(issueLabels.issueId, issueId),
   101	      ),
   102	    )
   103	    .run();
   104	
   105	  if (labelIds.length === 0) return;
   106	
   107	  db.insert(issueLabels)
   108	    .values(labelIds.map((labelId) => ({ orgId, issueId, labelId })))
   109	    .run();
   110	}
   111	
   112	/** Batched lookup keyed by issue id, so list views avoid an N+1. */
   113	export async function listLabelsForIssues(
   114	  orgId: OrgId,
   115	  issueIds: readonly IssueId[],
   116	): Promise<Readonly<Record<string, readonly IssueLabel[]>>> {
   117	  if (issueIds.length === 0) return {};
   118	
   119	  const rows = getDb()
   120	    .select({ issueId: issueLabels.issueId, label: labels })
   121	    .from(issueLabels)
   122	    .innerJoin(labels, eq(labels.id, issueLabels.labelId))
   123	    .where(
   124	      and(
   125	        orgPredicate(issueLabels.orgId, orgId),
   126	        inArray(issueLabels.issueId, [...issueIds]),
   127	      ),
   128	    )
   129	    .all();
   130	
   131	  const grouped: Record<string, IssueLabel[]> = {};
   132	  for (const row of rows) {
   133	    (grouped[row.issueId] ??= []).push(toLabel(row.label));
   134	  }
   135	  return grouped;
   136	}

