    55	 * for archived rows. The `includeArchived` decision itself lives in
    56	 * `shouldFilterArchived()` so it cannot drift per repository.
    57	 */
    58	export function livePredicate(
    59	  column: SQLiteColumn,
    60	  scope: ArchiveScope,
    61	): SQL | undefined {
    62	  return shouldFilterArchived(scope) ? isNull(column) : undefined;
    63	}

