 12	import { subscribe } from "@/lib/event-bus";
 13	import { PermissionDeniedError } from "@/lib/permissions";
 14	import * as issueRepo from "@/server/repositories/issue-repository";
 15	import * as issueService from "@/server/services/issue-service";
 16	import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
 17	import type { Tenant } from "../server/_support/fixtures";
 18	
 19	let cleanup: () => void;
 20	let tenant: Tenant;
 21	
 22	beforeAll(async () => {
 23	  cleanup = await useTemporaryDatabase();
 24	  tenant = await createTenant("issuesvc");
 25	});
 26	
 27	afterAll(() => {
 28	  cleanup();
 29	});
 30	
 31	describe("services/issue-service", () => {
 32	  it("refuses issue creation to an actor without issue:create", async () => {
 33	    await expect(
 34	      issueService.createIssue(
 35	        tenant.actors.viewer,
 36	        issueInput(tenant.org.id, tenant.project.id, { title: "Viewer can't do this" }),
 37	      ),
 38	    ).rejects.toBeInstanceOf(PermissionDeniedError);
 39	  });
 40	
 41	  it("refuses creation when the project is at its plan issue quota", async () => {
 42	    const quotaTenant = await createTenant("issuequota", "free");
 43	
 44	    // The free plan allows 100 issues per project; seed that many directly
 45	    // through the repository so the service boundary is the only thing under
 46	    // test here.
 47	    for (let number = 1; number <= 100; number += 1) {
 48	      await issueRepo.insertIssue(
 49	        issueInput(quotaTenant.org.id, quotaTenant.project.id, {
 50	          title: `Seed issue ${number}`,
 51	        }),
 52	        quotaTenant.actors.member.userId,
 53	        number,
 54	      );
 55	    }
 56	
 57	    await expect(
 58	      issueService.createIssue(
 59	        quotaTenant.actors.member,
 60	        issueInput(quotaTenant.org.id, quotaTenant.project.id, {
 61	          title: "One too many",
 62	        }),
 63	      ),
 64	    ).rejects.toThrow(/allows no more issues/);
 65	  });
 66	
 67	  it("emits issue.created with the persisted issue's fields", async () => {
 68	    const received: unknown[] = [];
 69	    const off = subscribe("issue.created", (payload) => {
 70	      received.push(payload);
 71	    });
 72	
 73	    try {
 74	      const issue = await issueService.createIssue(
 75	        tenant.actors.member,
 76	        issueInput(tenant.org.id, tenant.project.id, { title: "Ship the launch" }),
 77	      );
 78	
 79	      expect(received).toHaveLength(1);
 80	      expect(received[0]).toMatchObject({
 81	        issueId: issue.id,
 82	        projectId: issue.projectId,
 83	        title: issue.title,
 84	        priority: issue.priority,
 85	      });
 86	    } finally {
 87	      off();
 88	    }
 89	  });
 90	
 91	  it("emits issue.status_changed with the previous and new status", async () => {
 92	    const issue = await issueService.createIssue(
 93	      tenant.actors.member,
 94	      issueInput(tenant.org.id, tenant.project.id, { title: "Status change target" }),
 95	    );
 96	
 97	    const received: unknown[] = [];
 98	    const off = subscribe("issue.status_changed", (payload) => {
 99	      received.push(payload);
100	    });

