import { sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

/**
 * One row per successfully completed bulk import, keyed by the client-supplied
 * `importKey` within a workspace. A replay looks this row up instead of
 * writing issues again; a refused import never reaches this table, so the
 * same key is free to retry.
 */
export const issueImports = sqliteTable(
  "issue_imports",
  {
    id: idColumn(),
    ...tenantColumns,
    importKey: text("import_key").notNull(),
    projectId: text("project_id").notNull(),
    issueIds: text("issue_ids").notNull(),
    ...timestampColumns,
  },
  (table) => [
    uniqueIndex("issue_imports_org_key_idx").on(table.orgId, table.importKey),
  ],
);

export type IssueImportRow = typeof issueImports.$inferSelect;

