/**
 * The persisted record of a completed bulk import, keyed by `(orgId, importKey)`.
 */
import { and, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { parseJsonArray } from "./_mappers";
import type { IssueId, OrgId, ProjectId } from "@/types/common";

export interface IssueImportRecord {
  readonly importKey: string;
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
}

export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();

  if (!row) return null;

  return {
    importKey: row.importKey,
    projectId: row.projectId as ProjectId,
    issueIds: parseJsonArray<IssueId>(row.issueIds),
  };
}

export async function insertImport(
  orgId: OrgId,
  importKey: string,
  projectId: ProjectId,
  issueIds: readonly IssueId[],
): Promise<void> {
  const stamp = toIsoTimestamp(new Date());
  getDb()
    .insert(issueImports)
    .values({
      id: newId(),
      orgId,
      importKey,
      projectId,
      issueIds: JSON.stringify(issueIds),
      createdAt: stamp,
      updatedAt: stamp,
    })
    .run();
}

