/**
 * Bulk import: every row becomes an issue, in file order, after the same
 * gates as `createIssue` plus two batch-wide ones — the plan's per-project
 * quota and the workspace's issue-creation rate allowance both have to cover
 * the whole batch before anything is written. A key this workspace has
 * already imported short-circuits to the first result; a refused import never
 * reaches the point where the key would be recorded, so it is free to retry.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const existing = await issueImportRepo.findImport(input.orgId, input.importKey);
  if (existing) {
    const issues = await issueRepo.findIssuesByIds(input.orgId, existing.issueIds);
    return {
      importKey: input.importKey,
      projectId: existing.projectId,
      issues,
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assigneeByEmail = await resolveAssignees(input.orgId, input.rows);
  const labelIdByName = await resolveLabels(input.orgId, input.rows);

  let number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issues: Issue[] = [];

  for (const row of input.rows) {
    const labelIds = [
      ...new Set(row.labels.map((name) => labelIdByName.get(name))),
    ].filter((labelId): labelId is (typeof labelIdByName extends Map<string, infer V> ? V : never) => labelId !== undefined);

    const assigneeId = row.assigneeEmail
      ? (assigneeByEmail.get(row.assigneeEmail.toLowerCase()) ?? null)
      : null;

    const issue = await issueRepo.insertIssue(
      {
        orgId: input.orgId,
        projectId: input.projectId,
        title: row.title,
        description: row.description,
        status: row.status,
        priority: row.priority,
        assigneeId,
        parentId: null,
        estimate: null,
        dueAt: row.dueAt,
        labelIds,
      },
      actor.userId,
      number,
    );
    number += 1;
    issues.push(issue);
  }

  await issueImportRepo.insertImport(
    input.orgId,
    input.importKey,
    input.projectId,
    issues.map((issue) => issue.id),
  );

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds: issues.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues,
    replayed: false,
  };
}

/** Case-insensitive match against the workspace's active members; unmatched emails resolve to `undefined`. */
async function resolveAssignees(
  orgId: OrgId,
  rows: ImportIssuesInput["rows"],
): Promise<Map<string, UserId>> {
  const emails = new Set(
    rows
      .map((row) => row.assigneeEmail)
      .filter((email): email is string => email !== null)
      .map((email) => email.toLowerCase()),
  );

  const byEmail = new Map<string, UserId>();
  for (const email of emails) {
    const userId = await memberRepo.findActiveMemberUserIdByEmail(orgId, email);
    if (userId) byEmail.set(email, userId);
  }
  return byEmail;
}

/** Creates any label name that does not already exist, once per name. */
async function resolveLabels(
  orgId: OrgId,
  rows: ImportIssuesInput["rows"],
): Promise<Map<string, Issue["labelIds"][number]>> {
  const names = new Set(rows.flatMap((row) => row.labels));
  const byName = new Map<string, Issue["labelIds"][number]>();

  for (const name of names) {
    const existing = await labelRepo.findLabelByName(orgId, name);
    if (existing) {
      byName.set(name, existing.id);
      continue;
    }
    const created = await labelRepo.insertLabel({
      orgId,
      name,
      color: DEFAULT_LABEL_COLOR,
      description: null,
    });
    byName.set(name, created.id);
  }

  return byName;
}

